#!/usr/bin/env python3
import sys, os, re, math, time, signal, subprocess, tempfile, uuid, errno, stat

VERSION = "tspin 5.6.0"

COLOR_ORDER = ["default","black","red","green","yellow","blue","magenta","cyan","white","bright_black","bright_red","bright_green","bright_yellow","bright_blue","bright_magenta","bright_cyan","bright_white"]
FG_CODES = {"default":39,"black":30,"red":31,"green":32,"yellow":33,"blue":34,"magenta":35,"cyan":36,"white":37,"bright_black":90,"bright_red":91,"bright_green":92,"bright_yellow":93,"bright_blue":94,"bright_magenta":95,"bright_cyan":96,"bright_white":97}
BG_CODES = {"default":49,"black":40,"red":41,"green":42,"yellow":43,"blue":44,"magenta":45,"cyan":46,"white":47,"bright_black":100,"bright_red":101,"bright_green":102,"bright_yellow":103,"bright_blue":104,"bright_magenta":105,"bright_cyan":106,"bright_white":107}

class Style:
    __slots__=("fg","bg","bold","faint","italic","underline")
    def __init__(self, fg=None, bg=None, bold=False, faint=False, italic=False, underline=False):
        self.fg=fg; self.bg=bg; self.bold=bool(bold); self.faint=bool(faint); self.italic=bool(italic); self.underline=bool(underline)
    def is_empty(self):
        return self.fg is None and self.bg is None and not (self.bold or self.faint or self.italic or self.underline)
    def prefix(self):
        if self.is_empty(): return ""
        codes=[]
        if self.bold: codes.append("1")
        if self.faint: codes.append("2")
        if self.italic: codes.append("3")
        if self.underline: codes.append("4")
        if self.bg is not None: codes.append(str(BG_CODES[self.bg]))
        if self.fg is not None: codes.append(str(FG_CODES[self.fg]))
        return "\x1b["+";".join(codes)+"m"
    def render(self, text):
        if self.is_empty(): return text
        return self.prefix()+text+"\x1b[0m"
    def sort_key(self):
        def ck(c): return 0 if c is None else (COLOR_ORDER.index(c)+1)
        return (ck(self.fg), ck(self.bg), self.bold, self.faint, self.italic, self.underline)
    def __eq__(self, other):
        return isinstance(other,Style) and self.sort_key()==other.sort_key() and self.fg==other.fg and self.bg==other.bg and self.bold==other.bold and self.faint==other.faint and self.italic==other.italic and self.underline==other.underline
    def __hash__(self):
        return hash((self.fg,self.bg,self.bold,self.faint,self.italic,self.underline))
    def __repr__(self): return f"Style({self.fg!r},{self.bg!r},{self.bold},{self.faint},{self.italic},{self.underline})"

def S(fg=None,bg=None,bold=False,faint=False,italic=False,underline=False):
    return Style(fg,bg,bold,faint,italic,underline)

class Chunk:
    __slots__=("text","style","force_reset")
    def __init__(self,text,style=None,force_reset=False):
        self.text=text
        if style is not None and style.is_empty() and not force_reset:
            style=None
        self.style=style
        self.force_reset=force_reset
    def is_plain(self):
        return self.style is None
    def render(self):
        if self.style is None: return self.text
        if self.force_reset and self.style.is_empty(): return self.text+"\x1b[0m"
        return self.style.render(self.text)
    def __repr__(self): return f"Chunk({self.text!r},{self.style!r})"

def coalesce(chunks):
    out=[]
    for c in chunks:
        if c.text=="" and c.style is None:
            continue
        if out and out[-1].style is None and c.style is None:
            out[-1]=Chunk(out[-1].text+c.text,None)
        else:
            out.append(c)
    return out

def render_chunks(chunks):
    return "".join(c.render() for c in chunks)

# ---------------- TOML parsing ----------------
class TomlError(Exception):
    def __init__(self, message, line=1, col=1, span=1, source_line=""):
        super().__init__(message)
        self.message=message; self.line=line; self.col=col; self.span=max(1,span); self.source_line=source_line

class TVal:
    __slots__=("kind","value","line","col","span","raw")
    def __init__(self,kind,value,line=1,col=1,span=1,raw=None):
        self.kind=kind; self.value=value; self.line=line; self.col=col; self.span=span; self.raw=raw
    def describe(self):
        if self.kind=="string": return 'string "%s"' % self.value
        if self.kind=="integer": return "integer `%s`" % self.raw
        if self.kind=="float": return "floating point `%s`" % self.raw
        if self.kind=="bool": return "boolean `%s`" % ("true" if self.value else "false")
        if self.kind=="array": return "sequence"
        if self.kind=="table": return "map"
        if self.kind=="datetime": return "datetime"
        return self.kind

class TTable(dict):
