            if ch in " \t\r" or (allow_newline and ch=="\n"):
                self.advance()
            elif ch=="#":
                while self.i<self.n and self.text[self.i]!="\n": self.advance()
            else: break
    def expect_eol(self):
        self.skip_spaces_tabs()
        if self.i<self.n and self.text[self.i]=="#":
            while self.i<self.n and self.text[self.i]!="\n": self.advance()
        if self.i<self.n:
            if self.text[self.i]=="\r": self.advance()
            if self.i<self.n and self.text[self.i]=="\n": self.advance(); return
            if self.i<self.n:
