 "urls.http":S(fg="red",faint=True),"urls.https":S(fg="green",faint=True),"urls.host":S(fg="blue",faint=True),"urls.path":S(fg="blue"),"urls.query_params_key":S(fg="magenta"),"urls.query_params_value":S(fg="cyan"),"urls.symbols":S(fg="red"),
 "pointers.number":S(fg="blue",italic=True),"pointers.letter":S(fg="magenta",italic=True),"pointers.separator":S(faint=True),"pointers.x":S(fg="red"),
 "dates.date":S(fg="magenta"),"dates.time":S(fg="blue"),"dates.zone":S(fg="red"),"dates.separator":S(faint=True),
