}
DEFAULT_SEP_TOKEN="•"
DEFAULT_QUOTE_TOKEN='"'

class Theme:
    def __init__(self):
        self.styles=dict(DEFAULT_STYLES)
        self.separator_token=DEFAULT_SEP_TOKEN
        self.quotes_token=DEFAULT_QUOTE_TOKEN
        self.keywords=[]  # list of (words list, Style)
    def style(self,name): return self.styles[name]

def toml_error_with_source(parser_lines, msg,line,col,span):
    src=parser_lines[line-1] if 1<=line<=len(parser_lines) else ""
    e=TomlError(msg,line,col,span,src); return e

class ThemeLoader:
    def __init__(self,text):
        self.text=text; self.lines=text.split("\n"); self.theme=Theme()
    def err_at(self,val,msg,span=None,col=None,line=None):
        l=val.line if line is None else line; c=val.col if col is None else col; sp=val.span if span is None else span
        src=self.lines[l-1] if 1<=l<=len(self.lines) else ""
        raise TomlError(msg,l,c,sp,src)
    def parse(self):
        parser=TomlParser(self.text)
        try:
            root=parser.parse()
        except TomlError as e:
            if not e.source_line and 1<=e.line<=len(self.lines): e.source_line=self.lines[e.line-1]
            raise
        # Convert in document order
        for key,tval in root.items():
            if key in STRUCTS:
                self.convert_struct(key,tval)
            elif key=="keywords":
                self.convert_keywords(tval, root)
            else:
                continue
        return self.theme
    def convert_struct(self, top, tval):
        struct_name, fields = STRUCTS[top]
        if tval.kind=="table":
            tbl=tval.value
            field_map={n:t for n,t in fields}
            for fname,fval in tbl.items():
                if fname not in field_map: continue
                typ=field_map[fname]
                if typ=="style":
                    self.theme.styles[f"{top}.{fname}"]=self.convert_style(fval)
                elif typ=="char":
                    ch=self.convert_char(fval)
                    if top=="pointers": self.theme.separator_token=ch
                    elif top=="quotes": self.theme.quotes_token=ch
            return
        if tval.kind=="array":
            items=tval.value; n=len(fields)
            if len(items)<n:
                word="element" if n==1 else "elements"
                self.err_at(tval,f"invalid length {len(items)}, expected struct {struct_name} with {n} {word}")
            for (fname,typ),fval in zip(fields,items):
                if typ=="style": self.theme.styles[f"{top}.{fname}"]=self.convert_style(fval)
                else:
                    ch=self.convert_char(fval)
                    if top=="pointers": self.theme.separator_token=ch
                    elif top=="quotes": self.theme.quotes_token=ch
            return
        self.err_at(tval,f"invalid type: {tval.describe()}, expected struct {struct_name}")
    def convert_char(self,val):
        if val.kind!="string":
            # serde char errors in toml are like invalid type integer expected a character
            self.err_at(val,f"invalid type: {val.describe()}, expected a character")
        if len(val.value)!=1:
            self.err_at(val,f'invalid value: string "{val.value}", expected a character')
        return val.value
    def convert_color(self,val):
        # accepts string variant or single-key table {variant={}}
        if val.kind=="string":
            if val.value not in COLOR_ORDER:
                exp=", ".join("`%s`"%c for c in COLOR_ORDER)
                self.err_at(val,f"unknown variant `{val.value}`, expected one of {exp}")
            return val.value
        if val.kind=="table":
            tbl=val.value
            if len(tbl)==0:
                self.err_at(val,"wanted exactly 1 element, found 0 elements")
            if len(tbl)>1:
                self.err_at(val,"wanted exactly 1 element, more than 1 element")
            k=next(iter(tbl.keys())); v=tbl[k]; kline,kcol,kspan=tbl.key_pos.get(k,(v.line,v.col,v.span))
            # key position in inline table values: parser recorded bare key position
            if k not in COLOR_ORDER:
                exp=", ".join("`%s`"%c for c in COLOR_ORDER)
                src=self.lines[kline-1] if 1<=kline<=len(self.lines) else ""
                raise TomlError(f"unknown variant `{k}`, expected one of {exp}",kline,kcol,kspan,src)
            if v.kind!="table":
                self.err_at(v,f"expected table, found {v.kind if v.kind!='integer' else 'integer'}")
            # unit variant table should be empty? serde may accept empty map only; nonempty may error unknown field but ignore for now
            return k
        self.err_at(val,"wanted string or table")
    def convert_style(self,val):
        if val.kind=="table":
            tbl=val.value; fg=None;bg=None;bold=False;faint=False;italic=False;underline=False
            for fname,fval in tbl.items():
                if fname=="fg": fg=self.convert_color(fval)
                elif fname=="bg": bg=self.convert_color(fval)
                elif fname=="bold": bold=self.convert_bool(fval)
                elif fname=="faint": faint=self.convert_bool(fval)
                elif fname=="italic": italic=self.convert_bool(fval)
                elif fname=="underline": underline=self.convert_bool(fval)
                else: continue
            return Style(fg,bg,bold,faint,italic,underline)
        if val.kind=="array":
            items=val.value
            vals=[None,None,False,False,False,False]
            for idx,item in enumerate(items[:6]):
                if idx<2: vals[idx]=self.convert_color(item)
                else: vals[idx]=self.convert_bool(item)
            return Style(vals[0],vals[1],vals[2],vals[3],vals[4],vals[5])
        self.err_at(val,f"invalid type: {val.describe()}, expected struct Style")
    def convert_bool(self,val):
        if val.kind!="bool": self.err_at(val,f"invalid type: {val.describe()}, expected a boolean")
        return val.value
    def convert_keywords(self,tval,root):
        if tval.kind!="array":
            self.err_at(tval,f"invalid type: {tval.describe()}, expected a sequence")
        for item in tval.value:
            self.convert_keyword_item(item)
    def convert_keyword_item(self,item):
        # KeywordToml fields words(seq string), style(Style) both required
        if item.kind=="table":
            tbl=item.value
            # validate present fields in document order first? serde checks invalid types while reading, missing after.
            words=None; style=None
            for fname,fval in tbl.items():
                if fname=="words": words=self.convert_words(fval)
                elif fname=="style": style=self.convert_style(fval)
                else: continue
            if words is None:
                src=self.lines[tbl.line-1] if 1<=tbl.line<=len(self.lines) else ""
                raise TomlError("missing field `words`",tbl.line,tbl.col,tbl.span,src)
            if style is None:
                src=self.lines[tbl.line-1] if 1<=tbl.line<=len(self.lines) else ""
                raise TomlError("missing field `style`",tbl.line,tbl.col,tbl.span,src)
            self.theme.keywords.append((words,style)); return
        if item.kind=="array":
            items=item.value
            if len(items)<2:
                self.err_at(item,f"invalid length {len(items)}, expected struct KeywordToml with 2 elements")
            words=self.convert_words(items[0]); style=self.convert_style(items[1]); self.theme.keywords.append((words,style)); return
        self.err_at(item,f"invalid type: {item.describe()}, expected struct KeywordToml")
    def convert_words(self,val):
        if val.kind!="array": self.err_at(val,f"invalid type: {val.describe()}, expected a sequence")
        out=[]
        for it in val.value:
            if it.kind!="string": self.err_at(it,f"invalid type: {it.describe()}, expected a string")
            out.append(it.value)
        return out
