    def __init__(self, fg=None, bg=None, bold=False, faint=False, italic=False, underline=False):
        self.fg=fg; self.bg=bg; self.bold=bool(bold); self.faint=bool(faint); self.italic=bool(italic); self.underline=bool(underline)
    def is_empty(self):
        return self.fg is None and self.bg is None and not (self.bold or self.faint or self.italic or self.underline)
    def prefix(self):
        if self.is_empty(): return ""
        codes=[]
        if self.bold: codes.append("1")
        if self.faint: codes.append("2")
        if self.italic: codes.append("3")
        if self.underline: codes.append("4")
        if self.bg is not None: codes.append(str(BG_CODES[self.bg]))
        if self.fg is not None: codes.append(str(FG_CODES[self.fg]))
        return "\x1b["+";".join(codes)+"m"
    def render(self, text):
        if self.is_empty(): return text
        return self.prefix()+text+"\x1b[0m"
    def sort_key(self):
        def ck(c): return 0 if c is None else (COLOR_ORDER.index(c)+1)
        return (ck(self.fg), ck(self.bg), self.bold, self.faint, self.italic, self.underline)
    def __eq__(self, other):
        return isinstance(other,Style) and self.sort_key()==other.sort_key() and self.fg==other.fg and self.bg==other.bg and self.bold==other.bold and self.faint==other.faint and self.italic==other.italic and self.underline==other.underline
    def __hash__(self):
        return hash((self.fg,self.bg,self.bold,self.faint,self.italic,self.underline))
    def __repr__(self): return f"Style({self.fg!r},{self.bg!r},{self.bold},{self.faint},{self.italic},{self.underline})"

def S(fg=None,bg=None,bold=False,faint=False,italic=False,underline=False):
    return Style(fg,bg,bold,faint,italic,underline)

class Chunk:
    __slots__=("text","style","force_reset")
    def __init__(self,text,style=None,force_reset=False):
        self.text=text
        if style is not None and style.is_empty() and not force_reset:
            style=None
        self.style=style
        self.force_reset=force_reset
    def is_plain(self):
        return self.style is None
    def render(self):
        if self.style is None: return self.text
        if self.force_reset and self.style.is_empty(): return self.text+"\x1b[0m"
        return self.style.render(self.text)
    def __repr__(self): return f"Chunk({self.text!r},{self.style!r})"

def coalesce(chunks):
    out=[]
    for c in chunks:
        if c.text=="" and c.style is None:
            continue
        if out and out[-1].style is None and c.style is None:
            out[-1]=Chunk(out[-1].text+c.text,None)
        else:
            out.append(c)
    return out

def render_chunks(chunks):
    return "".join(c.render() for c in chunks)

# ---------------- TOML parsing ----------------
class TomlError(Exception):
    def __init__(self, message, line=1, col=1, span=1, source_line=""):
        super().__init__(message)
        self.message=message; self.line=line; self.col=col; self.span=max(1,span); self.source_line=source_line

class TVal:
    __slots__=("kind","value","line","col","span","raw")
    def __init__(self,kind,value,line=1,col=1,span=1,raw=None):
        self.kind=kind; self.value=value; self.line=line; self.col=col; self.span=span; self.raw=raw
    def describe(self):
        if self.kind=="string": return 'string "%s"' % self.value
        if self.kind=="integer": return "integer `%s`" % self.raw
        if self.kind=="float": return "floating point `%s`" % self.raw
        if self.kind=="bool": return "boolean `%s`" % ("true" if self.value else "false")
        if self.kind=="array": return "sequence"
        if self.kind=="table": return "map"
        if self.kind=="datetime": return "datetime"
        return self.kind

class TTable(dict):
    def __init__(self,line=1,col=1,span=1):
        super().__init__(); self.line=line; self.col=col; self.span=span; self.key_pos={}

# A small TOML parser sufficient for theme files, with positions for error reporting.
class TomlParser:
    def __init__(self,text):
        self.text=text; self.n=len(text); self.i=0; self.line=1; self.col=1
        self.lines=text.split("\n")
        self.root=TTable(1,1,1)
        self.current=self.root
        self.defined_tables=set()
        self.defined_keys=set()  # id(table),key
    def err(self,msg,line=None,col=None,span=1):
        line=self.line if line is None else line; col=self.col if col is None else col
        src=self.lines[line-1] if 1<=line<=len(self.lines) else ""
        raise TomlError(msg,line,col,span,src)
    def peek(self):
        return self.text[self.i] if self.i<self.n else ""
    def startswith(self,s): return self.text.startswith(s,self.i)
    def advance(self,count=1):
        for _ in range(count):
            if self.i>=self.n: break
            ch=self.text[self.i]; self.i+=1
            if ch=="\n": self.line+=1; self.col=1
            else: self.col+=1
    def pos(self): return (self.line,self.col)
    def skip_spaces_tabs(self):
        while self.i<self.n and self.text[self.i] in " \t": self.advance()
    def skip_ws_comments_newlines(self, allow_newline=True):
        while self.i<self.n:
            ch=self.text[self.i]
            if ch in " \t\r" or (allow_newline and ch=="\n"):
                self.advance()
            elif ch=="#":
                while self.i<self.n and self.text[self.i]!="\n": self.advance()
            else: break
    def expect_eol(self):
        self.skip_spaces_tabs()
        if self.i<self.n and self.text[self.i]=="#":
            while self.i<self.n and self.text[self.i]!="\n": self.advance()
        if self.i<self.n:
            if self.text[self.i]=="\r": self.advance()
            if self.i<self.n and self.text[self.i]=="\n": self.advance(); return
            if self.i<self.n:
                # determine a reasonable source span (rest of token)
                self.err("expected newline, `#`")
    def parse(self):
        while True:
            self.skip_ws_comments_newlines()
            if self.i>=self.n: break
            if self.peek()=="[":
                self.parse_header()
            else:
                self.parse_keyval(self.current)
            self.expect_eol()
        return self.root
    def parse_key(self):
        parts=[]; poss=[]
        while True:
            self.skip_spaces_tabs(); line,col=self.pos()
            ch=self.peek()
            if ch in "\"'":
                v=self.parse_string()
                key=v.value; span=v.span
            else:
                start=self.i
                while self.i<self.n and (self.text[self.i].isalnum() or self.text[self.i] in "_-"):
                    self.advance()
                if start==self.i:
                    self.err("expected a table key, found a right bracket" if ch=="]" else "invalid key",line,col,1)
                key=self.text[start:self.i]; span=self.i-start
            parts.append(key); poss.append((line,col,span))
            self.skip_spaces_tabs()
            if self.peek()==".":
                self.advance(); continue
            break
        return parts,poss
    def navigate(self, parts, poss, create_array=False, for_header=False):
        cur=self.root
        for idx,part in enumerate(parts):
            is_last=(idx==len(parts)-1)
            if isinstance(cur, list):
                if not cur: cur.append(TTable(*poss[idx][:2],poss[idx][2]))
                cur=cur[-1]
            if not isinstance(cur, TTable):
                self.err("duplicate key `%s`" % part, poss[idx][0],poss[idx][1],poss[idx][2])
            if part not in cur:
                if is_last and create_array:
                    lst=[]; cur[part]=TVal("array",lst,poss[idx][0],poss[idx][1],poss[idx][2]); cur.key_pos[part]=poss[idx]
                    tbl=TTable(poss[idx][0],poss[idx][1],poss[idx][2]); lst.append(TVal("table",tbl,poss[idx][0],poss[idx][1],poss[idx][2])); return tbl
                else:
                    tbl=TTable(poss[idx][0],poss[idx][1],poss[idx][2])
                    cur[part]=TVal("table",tbl,poss[idx][0],poss[idx][1],poss[idx][2]); cur.key_pos[part]=poss[idx]; cur=tbl
            else:
                tv=cur[part]
                if is_last and create_array:
                    if tv.kind!="array":
                        self.err("duplicate key `%s`" % part, poss[idx][0],poss[idx][1],poss[idx][2])
                    tbl=TTable(poss[idx][0],poss[idx][1],poss[idx][2]); tv.value.append(TVal("table",tbl,poss[idx][0],poss[idx][1],poss[idx][2])); return tbl
                if tv.kind=="table": cur=tv.value
                elif tv.kind=="array":
                    if not tv.value: tv.value.append(TVal("table",TTable(poss[idx][0],poss[idx][1],poss[idx][2]),poss[idx][0],poss[idx][1],poss[idx][2]))
                    last=tv.value[-1]
                    if last.kind!="table": self.err("duplicate key `%s`" % part, poss[idx][0],poss[idx][1],poss[idx][2])
                    cur=last.value
                else:
                    self.err("duplicate key `%s`" % part, poss[idx][0],poss[idx][1],poss[idx][2])
        return cur
    def parse_header(self):
        start_line,start_col=self.pos(); start_i=self.i
        is_array=False
        self.advance() # [
        if self.peek()=="[":
            is_array=True; self.advance()
        parts,poss=self.parse_key()
        self.skip_spaces_tabs()
        if is_array:
            if not self.startswith("]]"): self.err("expected `]]`")
            self.advance(2)
        else:
            if self.peek()!="]": self.err("expected `]`")
            self.advance()
        header_span=self.i-start_i
        keypath=tuple(parts)
        if not is_array:
            if keypath in self.defined_tables:
                self.err("duplicate key `%s`" % parts[-1],start_line,start_col,header_span)
            self.defined_tables.add(keypath)
        tbl=self.navigate(parts,poss,create_array=is_array)
        # remember header location for missing field errors
        tbl.line=start_line; tbl.col=start_col; tbl.span=header_span
        self.current=tbl
    def assign(self, table, parts, poss, val):
        cur=table
        for idx,part in enumerate(parts):
            is_last=(idx==len(parts)-1)
            if isinstance(cur,list): cur=cur[-1].value
            if not isinstance(cur,TTable):
                self.err("duplicate key `%s`" % part, poss[idx][0],poss[idx][1],poss[idx][2])
            if is_last:
                if part in cur:
                    self.err("duplicate key `%s`" % part, poss[idx][0],poss[idx][1],poss[idx][2])
                cur[part]=val; cur.key_pos[part]=poss[idx]
            else:
                if part not in cur:
                    tbl=TTable(poss[idx][0],poss[idx][1],poss[idx][2]); cur[part]=TVal("table",tbl,poss[idx][0],poss[idx][1],poss[idx][2]); cur.key_pos[part]=poss[idx]; cur=tbl
                else:
                    tv=cur[part]
                    if tv.kind=="table": cur=tv.value
                    elif tv.kind=="array" and tv.value and tv.value[-1].kind=="table": cur=tv.value[-1].value
                    else: self.err("duplicate key `%s`" % part, poss[idx][0],poss[idx][1],poss[idx][2])
    def parse_keyval(self, table):
        start_line,start_col=self.pos()
        parts,poss=self.parse_key()
        self.skip_spaces_tabs()
        if self.peek()!="=":
            # span: current char
            self.err("key with no value, expected `=`", self.line, self.col, 1)
        self.advance(); self.skip_spaces_tabs()
        val=self.parse_value()
        self.assign(table,parts,poss,val)
    def parse_value(self):
        self.skip_spaces_tabs(); line,col=self.pos(); start=self.i; ch=self.peek()
        if ch=="": self.err("expected value",line,col,1)
        if ch in "\"'": return self.parse_string()
        if ch=="[":
            return self.parse_array()
        if ch=="{":
            return self.parse_inline_table()
        # bare token up to delimiter
        start_i=self.i
        while self.i<self.n and self.text[self.i] not in "\n,]}#":
            self.advance()
        raw=self.text[start_i:self.i].strip()
        raw_span=len(raw) if raw else 1
        if raw=="":
            self.err("expected value",line,col,1)
        if raw=="true" or raw=="false":
            return TVal("bool",raw=="true",line,col,raw_span,raw)
        # datetime detection (rough)
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}([Tt ]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})?)?",raw) or re.fullmatch(r"\d{2}:\d{2}:\d{2}(\.\d+)?",raw):
            return TVal("datetime",raw,line,col,raw_span,raw)
        # integers
        s=raw.replace("_","")
        try:
            if re.fullmatch(r"[+-]?0x[0-9A-Fa-f_]+",raw): val=int(s,16); return TVal("integer",val,line,col,raw_span,raw)
            if re.fullmatch(r"[+-]?0o[0-7_]+",raw): val=int(s,8); return TVal("integer",val,line,col,raw_span,raw)
            if re.fullmatch(r"[+-]?0b[01_]+",raw): val=int(s,2); return TVal("integer",val,line,col,raw_span,raw)
            if re.fullmatch(r"[+-]?\d[\d_]*",raw): 
                if re.fullmatch(r"[+-]?0\d+",s): raise ValueError
                return TVal("integer",int(s),line,col,raw_span,raw)
        except ValueError: pass
        # floats / inf nan
        if re.fullmatch(r"[+-]?(inf|nan)",raw):
            val=float(raw.replace("inf","inf")); return TVal("float",val,line,col,raw_span,raw)
        if re.fullmatch(r"[+-]?(\d[\d_]*(\.\d[\d_]*)?([eE][+-]?\d[\d_]*)?|\d[\d_]*\.\d[\d_]*|\.\d+)",raw) and ("." in raw or "e" in raw or "E" in raw):
            try:return TVal("float",float(s),line,col,raw_span,raw)
            except:pass
        # invalid bare value: position at end like toml crate often points next char, use token end
        # Determine a message similar to winnow parser
        self.err("invalid string\nexpected `\"`, `'`" if ch.isalpha() else "expected value", line, col+raw_span, 1)
    def parse_string(self):
        line,col=self.pos(); start=self.i; quote=self.peek()
        triple=self.startswith(quote*3)
        if triple: self.advance(3)
        else: self.advance()
        out=[]
        if triple:
            if self.peek()=="\n": self.advance()
            while self.i<self.n:
                if self.startswith(quote*3):
                    self.advance(3)
                    # up to two extra quotes are part of string in TOML, but rare
                    return TVal("string","".join(out),line,col,self.i-start)
                ch=self.text[self.i]
                if quote=='"' and ch=="\\":
                    # line-ending backslash
                    if self.i+1<self.n and self.text[self.i+1] in "\n":
                        self.advance(); 
                        while self.i<self.n and self.text[self.i] in " \t\n": self.advance()
                        continue
                    out.append(self.parse_escape(line,col))
                else:
                    out.append(ch); self.advance()
            self.err("unterminated string",line,col,3)
        else:
            while self.i<self.n:
                ch=self.text[self.i]
                if ch=="\n": self.err("newline in string",self.line,self.col,1)
                if ch==quote:
                    self.advance(); return TVal("string","".join(out),line,col,self.i-start)
                if quote=='"' and ch=="\\": out.append(self.parse_escape(line,col))
                else: out.append(ch); self.advance()
            self.err("unterminated string",line,col,1)
    def parse_escape(self,sline,scol):
        line,col=self.pos(); self.advance() # backslash
        if self.i>=self.n: self.err("invalid escape sequence",line,col,1)
        ch=self.text[self.i]; self.advance()
        mp={"b":"\b","t":"\t","n":"\n","f":"\f","r":"\r",'"':'"',"\\":"\\","e":"\x1b"}
        if ch in mp: return mp[ch]
        if ch=="u":
            hexs=self.text[self.i:self.i+4]
            if len(hexs)<4 or not re.fullmatch(r"[0-9A-Fa-f]{4}",hexs): self.err("invalid escape sequence",line,col,2)
            for _ in range(4): self.advance()
            code=int(hexs,16)
            try:return chr(code)
            except:self.err("invalid escape sequence",line,col,6)
        if ch=="U":
            hexs=self.text[self.i:self.i+8]
            if len(hexs)<8 or not re.fullmatch(r"[0-9A-Fa-f]{8}",hexs): self.err("invalid escape sequence",line,col,2)
            for _ in range(8): self.advance()
            code=int(hexs,16)
            try:return chr(code)
            except:self.err("invalid escape sequence",line,col,10)
        if ch=="x": # TOML 1.1 allows? accept two hex
            hexs=self.text[self.i:self.i+2]
            if len(hexs)<2 or not re.fullmatch(r"[0-9A-Fa-f]{2}",hexs): self.err("invalid escape sequence",line,col,2)
            for _ in range(2): self.advance()
            return chr(int(hexs,16))
        self.err("invalid escape sequence",line,col,2)
    def parse_array(self):
        line,col=self.pos(); start=self.i; self.advance(); items=[]
        while True:
            self.skip_ws_comments_newlines()
            if self.i>=self.n: self.err("expected `]`",line,col,1)
            if self.peek()=="]": self.advance(); break
            items.append(self.parse_value())
            self.skip_ws_comments_newlines()
            if self.peek()==",": self.advance(); continue
            if self.peek()=="]": self.advance(); break
            self.err("expected `,` or `]`")
        return TVal("array",items,line,col,self.i-start)
    def parse_inline_table(self):
        line,col=self.pos(); start=self.i; self.advance(); tbl=TTable(line,col,1)
        while True:
            self.skip_spaces_tabs()
            if self.i<self.n and self.text[self.i]=="\n":
                # TOML 1.1 allows newlines in inline tables; older toml crate used by reference may also
                self.skip_ws_comments_newlines()
            if self.i>=self.n: self.err("expected `}`",line,col,1)
            if self.peek()=="}": self.advance(); break
            kline,kcol=self.pos()
            parts,poss=self.parse_key(); self.skip_spaces_tabs()
            if self.peek()!="=": self.err("key with no value, expected `=`")
            self.advance(); self.skip_spaces_tabs(); val=self.parse_value(); self.assign(tbl,parts,poss,val)
            self.skip_spaces_tabs()
            if self.i<self.n and self.text[self.i]=="\n": self.skip_ws_comments_newlines()
            if self.peek()==",": self.advance(); continue
            if self.peek()=="}": self.advance(); break
            self.err("expected `}`")
        tbl.line=line;tbl.col=col;tbl.span=self.i-start
        return TVal("table",tbl,line,col,self.i-start)

def wrap_message(msg, width=76):
    # toml crate wraps long messages; approximate word wrap used by Rust toml error rendering
    words=msg.split(" ")
    lines=[]; cur=""
    for w in words:
        if cur=="" : cur=w
        elif len(cur)+1+len(w)<=width: cur+=" "+w
        else: lines.append(cur); cur=w
    if cur: lines.append(cur)
    return lines

def format_toml_error(err):
    msg=err.message; line=str(err.line); src=err.source_line
    # reproduce the toml crate's message wrapping for long enum lists observed:
    wrapped=wrap_message(msg,76)
    out=[]
    out.append(f"TOML parse error at line {err.line}, column {err.col}")
    out.append("  │   |")
    out.append(f"  │ {line} | {src}")
    pad=" " * (len(line))  # not exactly; use gutter below
    # caret line: two spaces, box, space, spaces matching "1 | " width, then col-1 spaces
    prefix=" "*(len(line)+3)  # for "  │ {line} | " -> after │, one space, line, space | space
    # Construct exactly as observed: "  │   |    ^" for line=1 col=4 (3 spaces then | then 4 spaces then caret)
    # General: spaces before | equals len(line)+2? observed len(line)=1 -> 3 spaces. caret indent = col (spaces)?? line1 col4 -> 4 spaces before caret after |
    caret_line="  │"+" "*(len(line)+2)+"|"+" "*err.col+"^"*err.span
    out.append(caret_line)
    for wl in wrapped:
        out.append("  │ "+wl)
    out.append("  │ ")
    return "\n".join(out)

def miette_error(msg, cause=None, help_text=None, code=None, symbol="×"):
    # Returns string without trailing blank handling handled by caller printing \n\n maybe
    if code:
        s=f"Error: {code}\n\n  × {msg}\n"
    else:
        s=f"Error:   {symbol} {msg}\n"
    if cause is not None:
        s+=f"  ╰─▶ {cause}\n"
    if help_text is not None:
        # help lines are prewrapped by caller
        s+=help_text
    return s

def print_miette(msg, cause=None, help_text=None, code=None, symbol="×"):
    txt=miette_error(msg,cause,help_text,code,symbol)
    # All observed Error reports end with an extra blank line
    sys.stderr.write(txt+"\n")

def raise_toml_type(val,msg):
    raise TomlError(msg,val.line,val.col,val.span,"")

