def wrap_message(msg, width=76):
    # toml crate wraps long messages; approximate word wrap used by Rust toml error rendering
    words=msg.split(" ")
    lines=[]; cur=""
    for w in words:
        if cur=="" : cur=w
        elif len(cur)+1+len(w)<=width: cur+=" "+w
        else: lines.append(cur); cur=w
    if cur: lines.append(cur)
    return lines

def format_toml_error(err):
    msg=err.message; line=str(err.line); src=err.source_line
    # reproduce the toml crate's message wrapping for long enum lists observed:
    wrapped=wrap_message(msg,76)
    out=[]
    out.append(f"TOML parse error at line {err.line}, column {err.col}")
    out.append("  │   |")
    out.append(f"  │ {line} | {src}")
    pad=" " * (len(line))  # not exactly; use gutter below
    # caret line: two spaces, box, space, spaces matching "1 | " width, then col-1 spaces
    prefix=" "*(len(line)+3)  # for "  │ {line} | " -> after │, one space, line, space | space
    # Construct exactly as observed: "  │   |    ^" for line=1 col=4 (3 spaces then | then 4 spaces then caret)
    # General: spaces before | equals len(line)+2? observed len(line)=1 -> 3 spaces. caret indent = col (spaces)?? line1 col4 -> 4 spaces before caret after |
    caret_line="  │"+" "*(len(line)+2)+"|"+" "*err.col+"^"*err.span
    out.append(caret_line)
    for wl in wrapped:
        out.append("  │ "+wl)
    out.append("  │ ")
    return "\n".join(out)

def miette_error(msg, cause=None, help_text=None, code=None, symbol="×"):
    # Returns string without trailing blank handling handled by caller printing \n\n maybe
    if code:
        s=f"Error: {code}\n\n  × {msg}\n"
    else:
        s=f"Error:   {symbol} {msg}\n"
    if cause is not None:
        s+=f"  ╰─▶ {cause}\n"
    if help_text is not None:
        # help lines are prewrapped by caller
        s+=help_text
    return s

def print_miette(msg, cause=None, help_text=None, code=None, symbol="×"):
    txt=miette_error(msg,cause,help_text,code,symbol)
    # All observed Error reports end with an extra blank line
    sys.stderr.write(txt+"\n")

