            for fname,fval in tbl.items():
                if fname not in field_map: continue
                typ=field_map[fname]
                if typ=="style":
                    self.theme.styles[f"{top}.{fname}"]=self.convert_style(fval)
                elif typ=="char":
                    ch=self.convert_char(fval)
                    if top=="pointers": self.theme.separator_token=ch
                    elif top=="quotes": self.theme.quotes_token=ch
            return
        if tval.kind=="array":
            items=tval.value; n=len(fields)
            if len(items)<n:
                word="element" if n==1 else "elements"
                self.err_at(tval,f"invalid length {len(items)}, expected struct {struct_name} with {n} {word}")
            for (fname,typ),fval in zip(fields,items):
                if typ=="style": self.theme.styles[f"{top}.{fname}"]=self.convert_style(fval)
                else:
                    ch=self.convert_char(fval)
                    if top=="pointers": self.theme.separator_token=ch
                    elif top=="quotes": self.theme.quotes_token=ch
            return
        self.err_at(tval,f"invalid type: {tval.describe()}, expected struct {struct_name}")
