BUILTIN_KEYWORDS=[
 (["TRACE"],S(faint=True)),
 (["INFO"],S(fg="white")),
 (["WARN"],S(fg="yellow")),
 (["ERROR"],S(fg="red")),
 (["DEBUG","SUCCESS"],S(fg="green")),
