# ---------------- JSON ----------------
class JsonNumber:
    __slots__=("text",)
    def __init__(self,text): self.text=text
class JsonParseError(Exception): pass

def format_f64_ryu(x):
    if x==0.0:
        return "-0.0" if math.copysign(1.0,x)<0 else "0.0"
    sign=""
    if x<0: sign="-"; x=-x
    # Use Python repr to get shortest digits, then reformat in Rust ryu style.
    r=repr(x)  # positive, may be like '1.23e+20' or '123.45' or '1000.0'
    # decompose into digits and decimal exponent: value = int(digits) * 10^e10_adjust, and digits has no dot/leading/trailing zeros except single zero handled
    if "e" in r or "E" in r:
        mant,exp=r.replace("E","e").split("e"); exp=int(exp)
    else:
        mant=r; exp=0
    if "." in mant:
        a,b=mant.split("."); digits=a+b; exp-=len(b)
    else:
        digits=mant
    # strip leading zeros
    digits=digits.lstrip("0") or "0"
    # strip trailing zeros adjusting exp
    while len(digits)>1 and digits.endswith("0"):
        digits=digits[:-1]; exp+=1
    # decimal exponent position: value = digits[0].digits[1:] * 10^dec_exp  where dec_exp = exp+len(digits)-1
    dec_exp=exp+len(digits)-1
    if dec_exp>=16 or dec_exp<=-6:
        if len(digits)==1: m=digits
        else:m=digits[0]+"."+digits[1:]
        return f"{sign}{m}e{dec_exp}"
    else:
        # fixed notation
        if dec_exp>=0:
            intlen=dec_exp+1
            if len(digits)<=intlen:
                intpart=digits+"0"*(intlen-len(digits)); frac=""
            else:
                intpart=digits[:intlen]; frac=digits[intlen:]
            if frac:
                return f"{sign}{intpart}.{frac}"
            else:
                return f"{sign}{intpart}.0"
        else:
            # 0.000ddd
            zeros=-dec_exp-1
            return f"{sign}0."+"0"*zeros+digits

def json_number_to_text(raw):
    # serde_json semantics: integer fitting i64/u64 preserved, -0 becomes -0.0, else f64 finite
    is_float=any(c in raw for c in ".eE")
    if not is_float:
        if raw=="-0":
            return "-0.0"
        try:
            val=int(raw)
        except: raise JsonParseError()
        if val>=0 and val<=18446744073709551615: return str(val)
        if val<0 and val>=-9223372036854775808: return str(val)
        # fall through to f64
    # parse f64 (Python float may overflow to inf)
    try:
        f=float(raw)
    except:
        raise JsonParseError()
    if not math.isfinite(f): raise JsonParseError()
    return format_f64_ryu(f)

class JsonParser:
    def __init__(self,text):
        self.s=text; self.i=0; self.n=len(text); self.depth=0
    def err(self): raise JsonParseError()
    def ws(self):
        while self.i<self.n and self.s[self.i] in " \t\n\r": self.i+=1
    def parse(self):
        self.ws(); v=self.value(); self.ws()
        if self.i!=self.n: self.err()
        return v
    def value(self):
        if self.i>=self.n:self.err()
        ch=self.s[self.i]
        if ch=="{": return self.obj()
        if ch=="[": return self.arr()
        if ch=='"': return self.string()
        if ch=="t":
            if self.s.startswith("true",self.i): self.i+=4; return True
            self.err()
        if ch=="f":
            if self.s.startswith("false",self.i): self.i+=5; return False
            self.err()
        if ch=="n":
            if self.s.startswith("null",self.i): self.i+=4; return None
            self.err()
        if ch=="-" or ch.isdigit(): return self.number()
        self.err()
    def enter(self):
        self.depth+=1
        if self.depth>127: self.err()
    def leave(self): self.depth-=1
    def obj(self):
        self.enter(); self.i+=1; self.ws(); d={}
        if self.i<self.n and self.s[self.i]=="}": self.i+=1; self.leave(); return d
        while True:
            self.ws()
            if self.i>=self.n or self.s[self.i]!='"': self.err()
            k=self.string(); self.ws()
            if self.i>=self.n or self.s[self.i]!=":": self.err()
            self.i+=1; self.ws(); v=self.value(); d[k]=v; self.ws()
            if self.i<self.n and self.s[self.i]==",": self.i+=1; continue
            if self.i<self.n and self.s[self.i]=="}": self.i+=1; break
            self.err()
        self.leave(); return d
    def arr(self):
        self.enter(); self.i+=1; self.ws(); out=[]
        if self.i<self.n and self.s[self.i]=="]": self.i+=1; self.leave(); return out
        while True:
            self.ws(); out.append(self.value()); self.ws()
            if self.i<self.n and self.s[self.i]==",": self.i+=1; continue
            if self.i<self.n and self.s[self.i]=="]": self.i+=1; break
            self.err()
        self.leave(); return out
    def string(self):
        # at quote
        self.i+=1; out=[]
        while self.i<self.n:
            ch=self.s[self.i]; self.i+=1
            if ch=='"': return "".join(out)
            if ord(ch)<0x20: self.err()
            if ch=="\\":
                if self.i>=self.n:self.err()
                esc=self.s[self.i]; self.i+=1
                mp={'"':'"',"\\":"\\","/":"/","b":"\b","f":"\f","n":"\n","r":"\r","t":"\t"}
                if esc in mp: out.append(mp[esc])
                elif esc=="u":
                    code=self.hex4()
                    if 0xD800<=code<=0xDBFF:
                        # high surrogate must be followed by \u low
                        if not self.s.startswith("\\u",self.i): self.err()
                        self.i+=2; lo=self.hex4()
                        if not (0xDC00<=lo<=0xDFFF): self.err()
                        cp=0x10000+((code-0xD800)<<10)+(lo-0xDC00); out.append(chr(cp))
                    elif 0xDC00<=code<=0xDFFF:
                        self.err()
                    else: out.append(chr(code))
                else:self.err()
            else:out.append(ch)
        self.err()
    def hex4(self):
        if self.i+4>self.n:self.err()
        h=self.s[self.i:self.i+4]
        if not re.fullmatch(r"[0-9A-Fa-f]{4}",h):self.err()
        self.i+=4; return int(h,16)
    def number(self):
        start=self.i
        if self.s[self.i]=="-":self.i+=1
        if self.i>=self.n:self.err()
        if self.s[self.i]=="0": self.i+=1
        elif self.s[self.i].isdigit() and self.s[self.i]!="0":
            while self.i<self.n and self.s[self.i].isdigit():self.i+=1
        else:self.err()
        if self.i<self.n and self.s[self.i]==".":
            self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit():self.err()
            while self.i<self.n and self.s[self.i].isdigit():self.i+=1
        if self.i<self.n and self.s[self.i] in "eE":
            self.i+=1
            if self.i<self.n and self.s[self.i] in "+-":self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit():self.err()
            while self.i<self.n and self.s[self.i].isdigit():self.i+=1
        raw=self.s[start:self.i]
        return JsonNumber(json_number_to_text(raw))

# Rendering parsed JSON to chunk list given theme
def json_to_chunks(v, theme):
    out=[]
    def q():
        out.append(Chunk('"',theme.style("json.quote_token")))
    def emit(x):
        if isinstance(x,dict):
            out.append(Chunk("{",theme.style("json.curly_bracket")))
            for idx,(k,val) in enumerate(x.items()):
                if idx>0: out.append(Chunk(",",theme.style("json.comma")))
                out.append(Chunk(" ",None)); q(); out.append(Chunk(k,theme.style("json.key"))); q(); out.append(Chunk(":",theme.style("json.colon"))); out.append(Chunk(" ",None)); emit(val)
            out.append(Chunk(" ",None)); out.append(Chunk("}",theme.style("json.curly_bracket")))
        elif isinstance(x,list):
            out.append(Chunk("[",theme.style("json.square_bracket")))
            for idx,val in enumerate(x):
                if idx>0: out.append(Chunk(",",theme.style("json.comma"))); out.append(Chunk(" ",None))
                emit(val)
            out.append(Chunk("]",theme.style("json.square_bracket")))
        elif isinstance(x,str):
            q(); 
            if x: out.append(Chunk(x,None))
            q()
        elif isinstance(x,JsonNumber):
            out.append(Chunk(x.text,None))
        elif x is True: out.append(Chunk("true",None))
        elif x is False: out.append(Chunk("false",None))
        elif x is None: out.append(Chunk("null",None))
    emit(v); return out

def try_json_chunks(line, theme):
    # Only attempt if after trimming JSON whitespace it looks like a JSON value; parser ensures full parse.
    # serde allows whitespace spaces/tabs/newlines/CR around. Lines have no newline, but \r may exist.
    t=line.strip(" \t\n\r")
    if t=="": return None
    # Optimization: first char must be valid start; parser would reject otherwise, but avoiding parser for plain words is fine as it rejects
    try:
        v=JsonParser(line).parse()
    except Exception:
        return None
    return json_to_chunks(v,theme)

# ---------------- Highlighters ----------------
ASCII=re.ASCII

def apply_regex(chunks, pattern, group_styles, group_transform=None):
    """group_styles: function(match)->list[Chunk] for the match, OR pattern performs custom.
       This generic function is a helper used by simple regex highlighters via a callback `make_chunks(match)` passed through group_styles if callable."""
    raise NotImplementedError

def apply_finder(chunks, finder):
    chunks=coalesce(chunks); out=[]
    for c in chunks:
        if c.style is not None:
            out.append(c)
        else:
            out.extend(finder(c.text))
    return out

def regex_finder(pattern, make_chunks):
    rx=re.compile(pattern, ASCII) if isinstance(pattern,str) else pattern
    def finder(text):
        out=[]; pos=0
        for m in rx.finditer(text):
            s,e=m.span()
            if s>pos: out.append(Chunk(text[pos:s],None))
            elif s<pos:
                continue
            # make_chunks may return None to indicate reject this candidate but consume it (advance beyond e, emit as plain)
            made=make_chunks(m)
            if made is None:
                # reject: consume candidate as plain (still could be matched by later highlighters after coalesce)
                out.append(Chunk(text[s:e],None)); pos=e; continue
            out.extend(made); pos=e
            if e==s:
                # zero-length: finditer will advance; if pos< len, next char should be emitted by subsequent prefix handling because next match start >=pos
                # To avoid an infinite zero loop in our logic, if next match starts same pos we will emit prefix below via continue guard s<pos etc. But python finditer handles moving.
                pass
        if pos<len(text): out.append(Chunk(text[pos:],None))
        return out
    return finder

# TIME before DATE
TIME_RE=re.compile(r"([T \t\r\n\x0b\x0c])?(2[0-3]|[01]?\d)(:)([0-5]\d)(:)([0-5]\d)(?:([.,])?(\d+)?)?(Z)?",ASCII)
def hl_time(chunks, theme):
    zone=theme.style("dates.zone"); tim=theme.style("dates.time"); sep=theme.style("dates.separator")
    def make(m):
        out=[]
        # groups: 1 zone prefix,2 hour,3 colon,4 min,5 colon,6 sec,7 fracsep,8 frac,9 Z
        if m.group(1) is not None: out.append(Chunk(m.group(1),zone))
        out.append(Chunk(m.group(2),tim)); out.append(Chunk(m.group(3),sep)); out.append(Chunk(m.group(4),tim)); out.append(Chunk(m.group(5),sep)); out.append(Chunk(m.group(6),tim))
        if m.group(7) is not None: out.append(Chunk(m.group(7),sep))
        if m.group(8) is not None: out.append(Chunk(m.group(8),tim))
        if m.group(9) is not None: out.append(Chunk(m.group(9),zone))
        return out
    return apply_finder(chunks, regex_finder(TIME_RE, make))

DATE_SMALL=r"(?:0[1-9]|[12]\d|3[01])"
DATE_YEAR=r"(?:19|20)\d\d"
DATE_RE=re.compile(rf"(?:({DATE_YEAR})([-/])({DATE_SMALL})([-/])({DATE_SMALL})|({DATE_SMALL})([-/])({DATE_SMALL})([-/])({DATE_YEAR}))",ASCII)
def hl_date(chunks, theme):
    date=theme.style("dates.date"); sep=theme.style("dates.separator")
    def make(m):
        if m.group(1) is not None:
            y,s1,a,s2,b=m.group(1),m.group(2),m.group(3),m.group(4),m.group(5)
        else:
            # DMY: a= g6, s1=g7, b=g8, s2=g9, y=g10 ; emit y,s1,a,s2,b
            a,s1,b,s2,y=m.group(6),m.group(7),m.group(8),m.group(9),m.group(10)
        return [Chunk(y,date),Chunk(s1,sep),Chunk(a,date),Chunk(s2,sep),Chunk(b,date)]
    return apply_finder(chunks, regex_finder(DATE_RE, make))

OCTET=r"(?:25[0-5]|2[0-4]\d|[01]?\d?\d)"
IPV4_BODY=rf"{OCTET}(?:\.{OCTET}){{3}}"
def is_valid_ipv4(s):
    return re.fullmatch(IPV4_BODY,s,ASCII) is not None

def is_valid_ipv6_token(tok):
    if tok=="::": return False
    if tok.count("::")>1: return False
    has_comp="::" in tok
    if has_comp:
        left,right=tok.split("::",1)
        left_groups=[] if left=="" else left.split(":")
        right_groups=[] if right=="" else right.split(":")
        groups=left_groups+right_groups
        if any(g=="" for g in groups): return False
    else:
        if tok.startswith(":") or tok.endswith(":"): return False
        groups=tok.split(":")
        if any(g=="" for g in groups): return False
    total=0
    for idx,g in enumerate(groups):
        if "." in g:
            # IPv4 can only be a whole tail consisting of 4 octets, starting at this group; in a token, the substring from this group should be ipv4 and be last 'group'
            # Our split by ':' made the IPv4 address one element containing dots only if it follows a colon; if token starts with ipv4 and no colon groups? then groups may be [ipv4] and no colon - not v6.
            if idx!=len(groups)-1:return False
            if not is_valid_ipv4(g): return False
            total+=2
        else:
            if not re.fullmatch(r"[0-9A-Fa-f]{1,4}",g):return False
            total+=1
    # must contain a colon (otherwise IPv4 or single hex)
    if ":" not in tok: return False
    if has_comp:
        # :: represents at least one group
        if total>7:return False
        if total==0:return False
        return True
    else:
        return total==8

IPV6_RUN_RE=re.compile(r"[0-9A-Fa-f:.]+")
def hl_ipv6(chunks, theme):
    num=theme.style("ip_addresses.number"); let=theme.style("ip_addresses.letter"); sep=theme.style("ip_addresses.separator")
    def char_style(ch):
        if ch.isdigit(): return num
        if ch in "abcdefABCDEF": return let
        return sep
    def finder(text):
        out=[]; pos=0
        for m in IPV6_RUN_RE.finditer(text):
            s,e=m.span(); tok=m.group(0)
            if not is_valid_ipv6_token(tok):
                continue
            # valid: emit prefix
            if s>pos: out.append(Chunk(text[pos:s],None))
            for ch in tok:
                out.append(Chunk(ch,char_style(ch)))
            pos=e
            # optional CIDR /digits 1-3
            if pos<len(text) and text[pos]=="/":
                j=pos+1; k=j
                while k<len(text) and text[k].isdigit() and k-j<3: k+=1
                if k>j:
                    out.append(Chunk("/",sep)); out.append(Chunk(text[j:k],num)); pos=k
        if pos<len(text): out.append(Chunk(text[pos:],None))
        return out
    return apply_finder(chunks,finder)

IPV4_RE=re.compile(rf"\b({OCTET})(\.)({OCTET})(\.)({OCTET})(\.)({OCTET})(?:(/)(\d{{1,2}}))?\b",ASCII)
def valid_ipv4_mask(mask):
    if len(mask)==1:return True
    return int(mask)<=32
def hl_ipv4(chunks, theme):
    num=theme.style("ip_addresses.number"); sep=theme.style("ip_addresses.separator")
    def make(m):
        # groups 1,2,3,4,5,6,7 octet/dot..., 8 slash,9 mask
        if m.group(8) is not None and not valid_ipv4_mask(m.group(9)):
            return None  # reject & consume candidate
        out=[]
        for idx in range(1,8):
            st=num if idx%2==1 else sep
            out.append(Chunk(m.group(idx),st))
        if m.group(8) is not None:
            out.append(Chunk(m.group(8),sep)); out.append(Chunk(m.group(9),num))
        return out
    return apply_finder(chunks, regex_finder(IPV4_RE, make))

URL_TAIL_STOP=set(" \t\n\r\x0b\x0c#")
URL_QUERY_RE=re.compile(r"([?&])([A-Za-z0-9_%+~.\-]*)=([A-Za-z0-9_%+~.\-]*)",ASCII)
def hl_urls(chunks, theme):
    def finder(text):
        out=[]; pos=0; i=0; n=len(text)
        host_re=re.compile(r"[A-Za-z0-9_.\-]+")
        path_re=re.compile(r"/[A-Za-z0-9_/%+~.\-]*")
        while i<n:
            scheme=None; scheme_style=None; slen=0
            if text.startswith("https://",i): scheme="https"; slen=5; scheme_style=theme.style("urls.https")
            elif text.startswith("http://",i): scheme="http"; slen=4; scheme_style=theme.style("urls.http")
            else: i+=1; continue
            j=i+slen+3
            hm=host_re.match(text,j)
            if not hm: i+=1; continue
            host=hm.group(0); j=hm.end()
            pm=path_re.match(text,j)
            if pm: path=pm.group(0); j=pm.end()
            else: path=""
            # prefix plain
            if i>pos: out.append(Chunk(text[pos:i],None))
            out.append(Chunk(scheme,scheme_style)); out.append(Chunk("://",None)); out.append(Chunk(host,theme.style("urls.host"))); out.append(Chunk(path,theme.style("urls.path")))
            # query tail if ?
            if j<n and text[j]=="?" :
                k=j
                while k<n and text[k] not in URL_TAIL_STOP: k+=1
                tail=text[j:k]
                # params inside tail
                tpos=0
                for qm in URL_QUERY_RE.finditer(tail):
                    qs,qe=qm.span()
                    if qs>tpos: out.append(Chunk(tail[tpos:qs],None))
                    sym,key,val=qm.group(1),qm.group(2),qm.group(3)
                    out.append(Chunk(sym,theme.style("urls.symbols"))); out.append(Chunk(key,theme.style("urls.query_params_key"))); out.append(Chunk("=",theme.style("urls.symbols"))); out.append(Chunk(val,theme.style("urls.query_params_value")))
                    tpos=qe
                if tpos<len(tail): out.append(Chunk(tail[tpos:],None))
                j=k
            pos=j; i=j
            if i<=0: i=pos+1
        if pos<n: out.append(Chunk(text[pos:],None))
        return out
    return apply_finder(chunks,finder)

PATH_SEG=r"[A-Za-z0-9_.\-]+"
PATH_RE=re.compile(rf"(?:/{{1,2}}{PATH_SEG}(?:/{PATH_SEG})+|(?:{PATH_SEG}|~)(?:/{PATH_SEG}){{2,}})",ASCII)
def hl_paths(chunks, theme):
    segstyle=theme.style("paths.segment"); sepstyle=theme.style("paths.separator")
    def make(m):
        txt=m.group(0); out=[]; cur=""
        for ch in txt:
            if ch=="/":
                if cur: out.append(Chunk(cur,segstyle)); cur=""
                out.append(Chunk("/",sepstyle))
            else:cur+=ch
        if cur: out.append(Chunk(cur,segstyle))
        return out
    return apply_finder(chunks, regex_finder(PATH_RE,make))

UUID_RE=re.compile(r"\b[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\b",ASCII)
def per_char_chunks(txt,num,let,sepchar_styles):
    out=[]
    for ch in txt:
        if ch.isdigit(): st=num
        elif ch.isalpha(): st=let
        else: st=sepchar_styles
        out.append(Chunk(ch,st))
    return out

def hl_uuids(chunks, theme):
    num=theme.style("uuids.number"); let=theme.style("uuids.letter"); dash=theme.style("uuids.dash")
    def make(m): return per_char_chunks(m.group(0),num,let,dash)
    return apply_finder(chunks, regex_finder(UUID_RE,make))

POINTER_RE=re.compile(r"\b0[xX][0-9A-Fa-f]{8}(?:[0-9A-Fa-f]{8})?\b",ASCII)
def hl_pointers(chunks, theme):
    num=theme.style("pointers.number"); let=theme.style("pointers.letter"); xs=theme.style("pointers.x"); sep=theme.style("pointers.separator"); token=theme.separator_token
    def make(m):
        txt=m.group(0); out=[Chunk("0",num),Chunk(txt[1],xs)]
        hexs=txt[2:]
        for idx,ch in enumerate(hexs):
            if idx==8 and len(hexs)==16: out.append(Chunk(token,sep))
            out.append(Chunk(ch, num if ch.isdigit() else let))
        return out
    return apply_finder(chunks, regex_finder(POINTER_RE,make))

PROCESS_RE=re.compile(r"(\([A-Za-z0-9_+\-./: ]+\)|[A-Za-z0-9_\-/]+)(\[)(\d+)(\])",ASCII)
def hl_processes(chunks, theme):
    name=theme.style("processes.name"); brack=theme.style("processes.bracket"); pid=theme.style("processes.id")
    def make(m): return [Chunk(m.group(1),name),Chunk(m.group(2),brack),Chunk(m.group(3),pid),Chunk(m.group(4),brack)]
    return apply_finder(chunks, regex_finder(PROCESS_RE,make))

KV_RE=re.compile(r"(?:^|(?<=[ \t\n\x0b\x0c\r]))([A-Za-z0-9_]+)(=)",ASCII)
def hl_kv(chunks, theme):
    k=theme.style("key_value_pairs.key"); sep=theme.style("key_value_pairs.separator")
    def make(m): return [Chunk(m.group(1),k),Chunk(m.group(2),sep)]
    return apply_finder(chunks, regex_finder(KV_RE,make))

NUMBER_RE=re.compile(r"\b\d+(?:\.\d+)?\b",ASCII)
def hl_numbers(chunks, theme):
    st=theme.style("numbers.number")
    def make(m): return [Chunk(m.group(0),st)]
    return apply_finder(chunks, regex_finder(NUMBER_RE,make))

BUILTIN_KEYWORDS=[
 (["TRACE"],S(faint=True)),
 (["INFO"],S(fg="white")),
 (["WARN"],S(fg="yellow")),
 (["ERROR"],S(fg="red")),
 (["DEBUG","SUCCESS"],S(fg="green")),
 (["true","false","null"],S(fg="red",italic=True)),
 (["GET"],S(fg="black",bg="green")),
 (["POST"],S(fg="black",bg="yellow")),
 (["PUT","PATCH"],S(fg="black",bg="magenta")),
 (["DELETE"],S(fg="black",bg="red")),
]

def hl_keywords(chunks, theme, cli_highlights, disable_builtin):
    # collect (words,style) groups, merge by style.
    by_style={}  # Style -> list of words in insertion order
    order=[]
    def add(words,style):
        key=style
        if key not in by_style: by_style[key]=[]; order.append(key)
        for w in words:
            if w not in by_style[key]: by_style[key].append(w)
    if not disable_builtin:
        for words,st in BUILTIN_KEYWORDS: add(words,st)
    for words,st in theme.keywords: add(words,st)
    for words,st in cli_highlights: add(words,st)
    if not by_style:return chunks
    sorted_styles=sorted(by_style.keys(), key=lambda s:s.sort_key())
    for st in sorted_styles:
        words=by_style[st]
        if not words: continue
        if "" in words:
            words=[""]
        pattern=r"(?<![A-Za-z0-9_])(?:%s)(?![A-Za-z0-9_])" % "|".join(re.escape(w) for w in words)
        rx=re.compile(pattern,ASCII)
        def make(m, st=st):
            txt=m.group(0)
            if st.bg is not None:
                txt=" "+txt+" "
            return [Chunk(txt,st)]
        chunks=apply_finder(chunks, regex_finder(rx,make))
    return chunks

def hl_quotes(chunks, theme):
    st=theme.style("quotes.style"); qchar=theme.quotes_token
    chunks=coalesce(chunks); out=[]
    for c in chunks:
        if c.style is not None:
            out.append(c); continue
        text=c.text
        if text.count(qchar)%2==1:
            out.append(c); continue
        if qchar not in text:
            out.append(c); continue
        indices=[i for i,ch in enumerate(text) if ch==qchar]
        pos=0
        for k in range(0,len(indices),2):
            a=indices[k]; b=indices[k+1]
            if a>pos: out.append(Chunk(text[pos:a],None))
            seg=text[a:b+1]
            if st.is_empty():
                out.append(Chunk(seg,Style(),force_reset=True))
            else:
                out.append(Chunk(seg,st))
            pos=b+1
        if pos<len(text): out.append(Chunk(text[pos:],None))
    return out

ALL_GROUPS=["numbers","urls","pointers","dates","paths","quotes","key-value-pairs","uuids","ip-addresses","processes","json"]

def highlight_line(line, theme, enabled_groups, cli_highlights, disable_builtin):
    # enabled_groups is a set of group names active
    if "json" in enabled_groups:
        jc=try_json_chunks(line,theme)
        chunks=jc if jc is not None else [Chunk(line,None)]
    else:
        chunks=[Chunk(line,None)]
    if "dates" in enabled_groups:
        chunks=hl_time(chunks,theme); chunks=hl_date(chunks,theme)
    if "ip-addresses" in enabled_groups:
        chunks=hl_ipv6(chunks,theme); chunks=hl_ipv4(chunks,theme)
    if "urls" in enabled_groups: chunks=hl_urls(chunks,theme)
    if "paths" in enabled_groups: chunks=hl_paths(chunks,theme)
    if "uuids" in enabled_groups: chunks=hl_uuids(chunks,theme)
