# Rendering parsed JSON to chunk list given theme
def json_to_chunks(v, theme):
    out=[]
    def q():
        out.append(Chunk('"',theme.style("json.quote_token")))
    def emit(x):
        if isinstance(x,dict):
            out.append(Chunk("{",theme.style("json.curly_bracket")))
            for idx,(k,val) in enumerate(x.items()):
                if idx>0: out.append(Chunk(",",theme.style("json.comma")))
                out.append(Chunk(" ",None)); q(); out.append(Chunk(k,theme.style("json.key"))); q(); out.append(Chunk(":",theme.style("json.colon"))); out.append(Chunk(" ",None)); emit(val)
            out.append(Chunk(" ",None)); out.append(Chunk("}",theme.style("json.curly_bracket")))
        elif isinstance(x,list):
            out.append(Chunk("[",theme.style("json.square_bracket")))
            for idx,val in enumerate(x):
                if idx>0: out.append(Chunk(",",theme.style("json.comma"))); out.append(Chunk(" ",None))
                emit(val)
            out.append(Chunk("]",theme.style("json.square_bracket")))
        elif isinstance(x,str):
            q(); 
            if x: out.append(Chunk(x,None))
            q()
        elif isinstance(x,JsonNumber):
            out.append(Chunk(x.text,None))
        elif x is True: out.append(Chunk("true",None))
        elif x is False: out.append(Chunk("false",None))
        elif x is None: out.append(Chunk("null",None))
    emit(v); return out

def try_json_chunks(line, theme):
    # Only attempt if after trimming JSON whitespace it looks like a JSON value; parser ensures full parse.
    # serde allows whitespace spaces/tabs/newlines/CR around. Lines have no newline, but \r may exist.
    t=line.strip(" \t\n\r")
    if t=="": return None
    # Optimization: first char must be valid start; parser would reject otherwise, but avoiding parser for plain words is fine as it rejects
    try:
        v=JsonParser(line).parse()
    except Exception:
        return None
    return json_to_chunks(v,theme)

