def os_error_string(e):
    # Errno string in Rust format: "<strerror> (os error N)"
    return f"{e.strerror} (os error {e.errno})"

def get_config_path(cli):
    if cli.config_path is not None:
        p=cli.config_path
        # Rust Path.exists() follows symlinks, false on any error.
        if not os.path.exists(p):
            print_miette("could not find the TOML file"); raise SystemExit(1)
        try:
            with open(p,"rb") as f: data=f.read()
        except OSError as e:
            print_miette(f"could not read the TOML file: {os_error_string(e)}",cause=os_error_string(e)); raise SystemExit(1)
        try:
            text=data.decode("utf-8")
        except UnicodeDecodeError as e:
            # Rust read_to_string error is InvalidData: stream did not contain valid UTF-8
            msg="stream did not contain valid UTF-8"
            print_miette(f"could not read the TOML file: {msg}",cause=msg); raise SystemExit(1)
        return text
    # determine default path
    xdg_present="XDG_CONFIG_HOME" in os.environ
    if xdg_present:
        base=os.environ.get("XDG_CONFIG_HOME","")
        path=os.path.join(base,"tailspin","theme.toml") if base else os.path.join("tailspin","theme.toml")
    else:
        if "HOME" not in os.environ:
            # check for invalid unicode HOME in environb? Python os.environ can represent it with surrogates; check bytes
            print_miette("could not determine the home environment: environment variable not found",cause="environment variable not found"); raise SystemExit(1)
        home=os.environ.get("HOME","")
        path=os.path.join(home,".config","tailspin","theme.toml") if home else os.path.join(".config","tailspin","theme.toml")
    if not os.path.exists(path):
        return None
    try:
        with open(path,"rb") as f:data=f.read()
    except OSError as e:
        print_miette(f"could not read the TOML file: {os_error_string(e)}",cause=os_error_string(e)); raise SystemExit(1)
    try:text=data.decode("utf-8")
    except UnicodeDecodeError:
        msg="stream did not contain valid UTF-8"; print_miette(f"could not read the TOML file: {msg}",cause=msg); raise SystemExit(1)
    return text

def load_theme(cli):
    text=get_config_path(cli)
    if text is None:return Theme()
    try:
        return ThemeLoader(text).parse()
    except TomlError as e:
        if not e.source_line:
            lines=text.split("\n"); e.source_line=lines[e.line-1] if 1<=e.line<=len(lines) else ""
        print_miette(format_toml_error(e)); raise SystemExit(1)

def resolve_enabled(cli):
    if cli.enable and cli.disable:
        print_miette("cannot both enable and disable highlighters"); raise SystemExit(1)
    if cli.enable:
        return set(cli.enable)
    s=set(ALL_GROUPS)
    for d in cli.disable:s.discard(d)
    return s
