class FileFollower:
    def __init__(self,cli,theme,enabled, write_line, stop_event):
        self.cli=cli;self.theme=theme;self.enabled=enabled;self.write_line=write_line;self.stop=stop_event
        self.fp=None;self.offset=0;self.path_missing=False;self.inode=None
    def emit_line(self,line,kind="file_next"):
        self.write_line(highlight_line(line,self.theme,self.enabled,self.cli.highlights,self.cli.disable_builtin))
    def do_initial(self):
        self.fp=open_input_file(self.cli)
        try:
            st=os.fstat(self.fp.fileno()); self.inode=(st.st_dev,st.st_ino)
        except:pass
        lines,offset,data=initial_file_lines(self.fp,self.cli)
        self.offset=offset
        # initial output: print/pager both use same. For print kind file_initial for broken pipe handling is set by write_line wrapper in caller.
        if not lines:
            self.write_line("")
        else:
            for line in lines:self.emit_line(line)
    def process_available(self):
        # check replacement after deletion
        try:
            pst=os.stat(self.cli.file); pin=(pst.st_dev,pst.st_ino)
            if self.path_missing and self.inode is not None and pin!=self.inode:
                try:self.fp.close()
                except:pass
                self.fp=open_input_file(self.cli); self.offset=0; self.inode=pin
            self.path_missing=False
        except FileNotFoundError:
            self.path_missing=True
        except OSError:
            self.path_missing=True
        if self.fp is None:return
        try:
            size=os.fstat(self.fp.fileno()).st_size
        except OSError:
            return
        if size<=self.offset:return
        try:
            self.fp.seek(self.offset); chunk=self.fp.read(size-self.offset)
        except OSError:
            return
        if not chunk:return
        self.offset+=len(chunk)
        # split chunk into segments by \n including final partial as segment
        start=0; segments=[]
        while True:
            idx=chunk.find(b"\n",start)
            if idx<0:
                if start<len(chunk):segments.append((chunk[start:],False))
                break
            segments.append((chunk[start:idx],True)); start=idx+1
            if start>=len(chunk):break
        for seg,terminated in segments:
            if terminated and seg.endswith(b"\r"): seg=seg[:-1]
            try:
                line=seg.decode("utf-8")
            except UnicodeDecodeError:
                raise NextLineUtf8Error()
            self.emit_line(line)
    def run(self):
        # assumes do_initial already called
        while not self.stop.is_set():
            self.process_available()
            # sleep a bit but responsive
            self.stop.wait(0.02)
    def close(self):
        try:
            if self.fp:self.fp.close()
        except:pass

