    stop=threading.Event()
    def wl(s): write_stdout_line(s,kind="file_initial")
    fol=FileFollower(cli,theme,enabled,wl,stop)
    try:
        fol.do_initial()
    except InitialReadFailed:
        return initial_failed_exit()
    # after initial, stdout broken pipe kind changes conceptually; our wl still says file_initial but BrokenPipe handling in main checks phase by exception attribute - approximate
    try:
        fol.run()
    except NextLineUtf8Error:
        print_miette("Could not read next line",cause="stream did not contain valid UTF-8"); return 1
    finally: fol.close()
    return 0

def file_pager(cli,theme,enabled):
    # custom pager parse validated in main before this.
    tmp=TempPagerFile(); stop=threading.Event(); errors=[]
    fol=FileFollower(cli,theme,enabled,tmp.write_line,stop)
    try:
        fol.do_initial()
    except InitialReadFailed:
        tmp.close(); return initial_failed_exit()
    def runner():
        try:fol.run()
        except Exception as e:errors.append(e)
    th=threading.Thread(target=runner,daemon=True); th.start()
    pager=None; status=0
    try:
        pager=launch_pager(cli,tmp.path,cli.follow)
        status=pager.wait()
    finally:
        stop.set(); th.join(timeout=0.3); fol.close(); tmp.close()
    for e in errors:
        if isinstance(e,NextLineUtf8Error):
            print_miette("Could not read next line",cause="stream did not contain valid UTF-8"); return 1
    return pager_status_error(status)

def exec_pager(cli,theme,enabled):
    tmp=TempPagerFile(); stop=threading.Event(); errors=[]; child_holder=[]
    def producer():
        child=spawn_exec(cli.exec); child_holder.append(child)
        try:
            rc=process_stream(child.stdout,theme,enabled,cli,tmp.write_line)
            if rc!=0:errors.append(StreamUtf8Error())
        except Exception as e:errors.append(e)
        finally:
            try:
                if child.poll() is None:
                    # If pager stopped us, kill; if stream EOF, wait briefly (process_stream only returns at EOF so child likely done)
                    try:child.wait(timeout=0.2)
                    except:
                        try:child.kill()
                        except:pass
                        child.wait()
            except:pass
    # For stream errors in exec pager, reference writes its own error via process_stream in print mode, but here process_stream prints stream utf8 error via print_miette directly which may duplicate if we also handle errors below.
    # To avoid duplicate, use a custom stream processing: temporarily, process_stream prints. Accept for now but suppress StreamUtf8Error below as it's from rc.
    th=threading.Thread(target=producer,daemon=True); th.start()
    status=0
    try:
        pager=launch_pager(cli,tmp.path,True); status=pager.wait()
    finally:
        stop.set()
        if child_holder:
            child=child_holder[0]
            if child.poll() is None:
                try:child.kill()
                except:pass
        th.join(timeout=0.3); tmp.close()
    # If producer had a genuine stream error, process_stream already printed it; return 1.
    if errors:
        return 1
    return pager_status_error(status)

