def validate_file_and_conflicts(cli):
    if cli.file is not None:
        if cli.exec is not None:
            print_miette("Cannot read from both file and \x1b[35m--listen-command\x1b[0m"); raise SystemExit(1)
        # Rust Path.exists() and is_file()
        if not os.path.exists(cli.file):
            # Error line has warning symbol and colored path in yellow
            sys.stderr.write(f"Error:   ⚠ \x1b[33m{cli.file}\x1b[0m: No such file or directory\n\n"); raise SystemExit(1)
        try:
            mode=os.stat(cli.file).st_mode
        except OSError:
            mode=0
        if not stat.S_ISREG(mode):
            print_miette("Path is not a file"); raise SystemExit(1)

def print_broken_pipe_panic(kind):
    import threading
    tid=threading.get_native_id()
    # Rust panic output (observed), written to stderr fd directly
    panic=(f"\nthread 'tokio-runtime-worker' ({tid}) panicked at /rustc/ac68faa20c58cbccd01ee7208bf3b6e93a7d7f96/library/std/src/io/stdio.rs:1165:9:\n"
           "failed printing to stdout: Broken pipe (os error 32)\n"
           "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    try:os.write(2,panic.encode())
    except:pass
    if kind=="file_initial":
        return initial_failed_exit()
    else:
        # miette wraps task panic message at width
        sys.stderr.write('Error:   × task 11 panicked with message "failed printing to stdout: Broken pipe (os\n  │ error 32)"\n\n')
        return 1

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    signal.signal(signal.SIGINT,signal.SIG_DFL)
    try:
        cli=parse_cli(argv)
        validate_file_and_conflicts(cli)
        enabled=resolve_enabled(cli)
        theme=load_theme(cli)
        # decide mode
        stdin_isatty=False
        try:stdin_isatty=sys.stdin.isatty()
        except:stdin_isatty=False
        if cli.file is not None:
            if cli.print:
                if cli.follow:return file_follow_print(cli,theme,enabled)
                else:return file_print(cli,theme,enabled)
            else:
                # validate custom pager syntax before opening/reading file (but after theme/config)
                if cli.pager is not None:
                    _=parse_custom_pager(cli)
                return file_pager(cli,theme,enabled)
        if not stdin_isatty:
            def wl(s):write_stdout_line(s,"stream")
            return process_stream(sys.stdin.buffer,theme,enabled,cli,wl)
        if cli.exec is not None:
            if cli.print:
                return process_exec_print(cli,theme,enabled)
            else:
                if cli.pager is not None:_=parse_custom_pager(cli)
                return exec_pager(cli,theme,enabled)
        stdout_text("Missing filename (\x1b[36mtspin --help\x1b[0m for help)\n")
        return 0
    except BrokenPipePanic as e:
        return print_broken_pipe_panic(e.kind)
    except BrokenPipeError:
        return print_broken_pipe_panic("stream")

if __name__=="__main__":
    raise SystemExit(main())
