class StreamLines:
    def __init__(self,fp):
        self.fp=fp; self.first=True; self.lookahead=None
    def __iter__(self):
        while True:
            if self.lookahead is not None:
                raw=self.lookahead; self.lookahead=None
            else:
                raw=self.fp.readline()
            if raw==b"": break
            terminated=raw.endswith(b"\n")
            content=raw[:-1] if terminated else raw
            try:
                decoded=content.decode("utf-8")
            except UnicodeDecodeError:
                if self.first and terminated:
