def initial_file_lines(fp,cli):
    """Returns (complete_lines_decoded, offset_after_last_newline, raw_complete_bytes). Raises InitialReadFailed on invalid complete portion."""
    try:
        data=fp.read()
    except OSError:
        raise InitialReadFailed()
    last_nl=data.rfind(b"\n")
    if last_nl<0:
        return [],0,data
    complete=data[:last_nl+1]
    try:
        text=complete.decode("utf-8")
    except UnicodeDecodeError:
        raise InitialReadFailed()
    lines=[]
    # splitlines semantics for CRLF in complete portion
    parts=text.split("\n")[:-1]
    for part in parts:
        if part.endswith("\r"): part=part[:-1]
        lines.append(part)
    return lines,last_nl+1,data

