import subprocess,re,math,struct
# import formatter from tspin
import importlib.util
spec=importlib.util.spec_from_file_location("tspin","tspin.py"); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
fmt=mod.format_f64_ryu

def rust_powi(base,exp):
    # Rust f64::powi likely uses intrinsic llvm.pow -> libm? But implement exponent by squaring with reciprocal for negative
    if exp==0:return 1.0
    if exp<0:
        return 1.0/rust_powi(base,-exp)
    # binary exponentiation left-to-right? typical exp_by_squaring iterative
    result=1.0; b=base; e=exp
    while e>0:
        if e&1:result=result*b
        e>>=1
        if e:b=b*b
    return result

def candidates(raw):
    # parse significand/exponent as JSON number
    m=re.fullmatch(r'(-?)(\d+)(?:\.(\d+))?(?:[eE]([+-]?\d+))?',raw)
    if not m:return {}
