        try:out['mul_pow_libm']=sign*sf*(10.0**exp)
        except OverflowError:out['mul_pow_libm']=math.inf*sign
        try:out['mul_powi']=sign*sf*rust_powi(10.0,exp)
        except OverflowError:out['mul_powi']=math.inf*sign
        try:
            if exp>=0:out['mul_pow_intconv']=sign*sf*float(10**exp)
            else:out['mul_pow_intconv']=sign*sf/float(10**(-exp))
        except OverflowError:out['mul_pow_intconv']=math.inf*sign
        try:out['div_powi']=sign*(sf/rust_powi(10.0,-exp) if exp<0 else sf*rust_powi(10.0,exp))
        except: out['div_powi']=math.nan
    return out

