 while True:
  if p.poll() is not None:
   while True:
    r,_,_=select.select([master],[],[],.05)
    if not r:break
    try:d=os.read(master,65536)
    except:break
    if not d:break
    out+=d
   break
  r,_,_=select.select([master],[],[],.05)
  if r:
   try:out+=os.read(master,65536)
   except:break
 os.close(master);return out
for cols in [40,80]:
 for args in [['--enable','foo'],['--unknown'],['--print','--follow=x']]:
  r=run('./executable',args,cols);o=run('/tmp/ours/executable',args,cols);print(cols,args,r==o)
  if r!=o:print('REF',r);print('OUR',o)
PY"}

